import { randomBytes } from 'node:crypto';
import { SignJWT } from 'jose';

/**
 * The secrets the self-hosted Supabase Auth container needs (P36).
 *
 * Generated by us rather than copied from a Supabase dashboard, because there
 * is no Supabase project any more. `pnpm --filter @integr8/auth keygen` prints
 * all three.
 */

/** Ten years. The key is rotated by rotating the secret, not by waiting. */
const SERVICE_ROLE_KEY_LIFETIME_SECONDS = 10 * 365 * 24 * 60 * 60;

/** `SUPABASE_AUTH_JWT_SECRET`: 48 random bytes, base64url. */
export function generateAuthJwtSecret(): string {
  return randomBytes(48).toString('base64url');
}

/**
 * `SUPABASE_AUTH_DB_PASSWORD`: 32 random bytes, base64url. It goes inside a
 * connection string, so it must not contain `+`, `/` or `=`.
 */
export function generateAuthDbPassword(): string {
  return randomBytes(32).toString('base64url');
}

/**
 * `SUPABASE_SERVICE_ROLE_KEY`: what the API presents to Auth's admin endpoints.
 *
 * Auth accepts an HS256 token signed with `GOTRUE_JWT_SECRET` whose `role` is
 * in `GOTRUE_JWT_ADMIN_ROLES`, and no key id. Auth uses the secret's characters
 * as the key, not a decoding of them, so the string is encoded as it is.
 */
export async function mintServiceRoleKey(secret: string, now: Date = new Date()): Promise<string> {
  const issuedAt = Math.floor(now.getTime() / 1000);
  return new SignJWT({ role: 'service_role' })
    .setProtectedHeader({ alg: 'HS256', typ: 'JWT' })
    .setIssuer('integr8')
    .setIssuedAt(issuedAt)
    .setExpirationTime(issuedAt + SERVICE_ROLE_KEY_LIFETIME_SECONDS)
    .sign(new TextEncoder().encode(secret));
}
